 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance,S=BindingFlags.NonPublic|BindingFlags.Static;
 static void Main(){var a=Assembly.LoadFrom("MedianGrassReplacement.dll");var far=a.GetType("MedianGrassReplacement.Systems.FarSideLightPolicy");var roadType=far.GetNestedType("Approach",BindingFlags.NonPublic);var road=Activator.CreateInstance(roadType);var roads=(IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(roadType));void Set(string n,object value)=>roadType.GetField(n,F).SetValue(road,value);Set("Left",new float3(-20,0,0));Set("Right",new float3(20,0,0));Set("Outward",new float2(0,1));Set("Incoming",new List<float3>{new float3(1,0,0)});Set("LaneMasks",new List<ushort>{1});Set("VehicleMask",(ushort)1);roads.Add(road);var nearest=a.GetType("MedianGrassReplacement.Systems.GardenCityLightPolicy").GetMethod("NearestForPhase",S);foreach(float distance in new[]{.5f,11.9f,12f,12.1f,20f}){var actor=new Transform{m_Position=new float3(-20+distance,0,0),m_Rotation=quaternion.identity};int result=(int)nearest.Invoke(null,new object[]{actor,roads,(ushort)1});if(result!=(distance<12?0:-1))throw new Exception("Source-radius reproduction changed");Console.WriteLine("OBSERVED: unique phase 1, distance="+distance+"m, source="+result);}Console.WriteLine("CONFIRMED LIMIT: native actor at a 40m road's centre has an unambiguous phase but no association because all outer curb anchors are >=12m away. Shared by custom styles. Synthetic primary-source input; not proof of a captured highway actor's native origin.");}
